<template><div v-if="item"><h1>{{ item.name }}</h1><p>Status: {{ item.displayStatus }}</p><AppButton @click="used">Mark used</AppButton><AppButton @click="discard">Mark discarded</AppButton><router-link :to="`/items/${item.id}/edit`">Edit</router-link></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {itemsApi} from '../api/client';import AppButton from '../components/AppButton.vue';const route=useRoute();const router=useRouter();const item=ref<any>(null);const load=async()=>item.value=(await itemsApi.get(route.params.id as string)).data;onMounted(load);const used=async()=>{await itemsApi.markUsed(route.params.id as string);router.push('/inventory');};const discard=async()=>{await itemsApi.markDiscarded(route.params.id as string);router.push('/inventory');};</script>
